{%- set v_label = (p.label ?? null) -%}
{%- set v_crumbs = (p.crumbs ?? null) -%}
{%- set v_landmarkLabel = (p.landmarkLabel ?? null) -%}
{%- set v_last = ui_sub(ui_len(v_crumbs), 1) -%}
{%- set c_5 -%}
  {%- set c_4 -%}
    {%- for v_c in ui_l(v_crumbs) %}
      {%- set v_i = loop.index0 -%}
      {%- set c_3 -%}
        {%- if ui_t(ui_lt(v_i, v_last)) %}
          {%- set c_1 -%}
            {{ ui_text(ui_get(v_c, ['name'])) }}
          {%- endset -%}
          {{ include('ui/link/link.html.twig', {'p': {'Href': '#/', 'Variant': 'muted', 'Size': 'sm', 'Attrs': ui_attrs(['data-testid', 'crumb'])}, 'children': c_1}, with_context = false) }}
          {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'chevron-right', 'Size': 16}}, with_context = false) }}
        {%- else %}
          {%- set c_2 -%}
            {{ ui_text(ui_get(v_c, ['name'])) }}
          {%- endset -%}
          {{ include('ui/inline/inline.html.twig', {'p': {'Class': 'font-medium text-foreground', 'Attrs': ui_attrs(['aria-current', 'page'])}, 'children': c_2}, with_context = false) }}
        {%- endif %}
      {%- endset -%}
      {{ include('ui/list/list-item.html.twig', {'p': {'Class': 'flex items-center gap-2'}, 'children': c_3}, with_context = false) }}
    {%- endfor %}
  {%- endset -%}
  {{ include('ui/list/list.html.twig', {'p': {'Class': 'm-0 flex list-none flex-wrap items-center gap-2 p-0 text-sm text-muted-foreground'}, 'children': c_4}, with_context = false) }}
{%- endset -%}
{{ include('ui/block/block.html.twig', {'p': {'Tag': 'nav', 'Attrs': ui_attrs(['aria-label', ui_coalesce([v_landmarkLabel, v_label]), 'data-testid', 'crumbs'])}, 'children': c_5}, with_context = false) }}
